	@Test
	void unsignedVarintsKeepPositiveBytesAndRoundTripEveryBitPattern() {
		List<Long> values = new ArrayList<>(List.of(0L, 240L, 241L, 2287L, 2288L, 67823L, 67824L,
				Long.MAX_VALUE, Long.MIN_VALUE, Long.MIN_VALUE + 128, -2L, -1L));
		SplittableRandom random = new SplittableRandom(6352);
		for (int i = 0; i < 512; i++) {
			values.add(random.nextLong());
		}
		values.sort(Long::compareUnsigned);
		byte[] previous = null;
		for (long value : values) {
			byte[] expected = reference(value);
			for (ByteOrder order : new ByteOrder[] { ByteOrder.BIG_ENDIAN, ByteOrder.LITTLE_ENDIAN }) {
				ByteBuffer encoded = ByteBuffer.allocate(Varint.calcLengthUnsigned(value)).order(order);
				Varint.writeUnsigned(encoded, value);
				assertThat(encoded.array()).isEqualTo(expected);
				ByteBuffer list = ByteBuffer.allocate(expected.length).order(order);
				Varint.writeListUnsigned(list, new long[] { value });
				assertThat(list.array()).isEqualTo(expected);
				assertThat(list.position()).isEqualTo(expected.length);
				assertThat(list.order()).isSameAs(order);
				assertThat(encoded.order()).isSameAs(order);
				encoded.flip();
				assertThat(Varint.readUnsigned(encoded)).isEqualTo(value);
				assertThat(encoded.hasRemaining()).isFalse();
			}
			if (previous != null) {
				assertThat(Arrays.compareUnsigned(previous, expected)).isLessThanOrEqualTo(0);
			}
			previous = expected;
		}
	}

	@Test
	void canonicalAndTruncatedRawRangesAgreeAcrossTheSignedBoundary() {
		byte[] low = TripleIndex.encodeKey("posc", 0, 20, Long.MIN_VALUE, 0);
		byte[] high = TripleIndex.encodeKey("posc", 0, 20, -2, 0);
		LmdbKeyRange range = new LmdbKeyRange(low, high, "posc");
		assertThat(range.decodedBounds()).isNotNull();
		assertThat(range.includes(new long[] { 10, 20, Long.MAX_VALUE, 0 })).isFalse();
		assertThat(range.includes(new long[] { 10, 20, Long.MIN_VALUE, 0 })).isTrue();
		assertThat(range.includes(new long[] { 10, 20, -2, 0 })).isFalse();
		byte[] truncated = Arrays.copyOf(low, 5);
		LmdbKeyRange rawLower = new LmdbKeyRange(truncated, null, "posc");
		LmdbKeyRange rawUpper = new LmdbKeyRange(null, truncated, "posc");
		assertThat(rawLower.decodedBounds()).isNull();
		assertThat(rawUpper.decodedBounds()).isNull();
		assertThat(rawLower.includes(new long[] { 10, 20, Long.MIN_VALUE, 0 })).isTrue();
		assertThat(rawLower.includes(new long[] { 10, 20, Long.MAX_VALUE, 0 })).isFalse();
		assertThat(rawUpper.includes(new long[] { 10, 20, Long.MIN_VALUE, 0 })).isFalse();
		assertThat(rawUpper.includes(new long[] { 10, 20, Long.MAX_VALUE, 0 })).isTrue();
	}

