	private static byte[] reference(long value) {
		BigInteger number = new BigInteger(Long.toUnsignedString(value));
		if (number.compareTo(BigInteger.valueOf(240)) <= 0) {
			return new byte[] { (byte) value };
		}
		if (number.compareTo(BigInteger.valueOf(2287)) <= 0) {
			long delta = value - 240;
			return new byte[] { (byte) (241 + delta / 256), (byte) delta };
		}
		if (number.compareTo(BigInteger.valueOf(67823)) <= 0) {
			long delta = value - 2288;
			return new byte[] { (byte) 249, (byte) (delta / 256), (byte) delta };
		}
		int size = Math.max(3, (number.bitLength() + 7) / 8);
		byte[] result = new byte[size + 1];
		result[0] = (byte) (247 + size);
		for (int i = 0; i < size; i++) {
			result[size - i] = number.shiftRight(8 * i).byteValue();
		}
		return result;
	}
